sys_atf_step.inputs:
(function(outputs, steps, stepResult) {
  var env = new x_fed_day2_ops.Day2Env();
  if (!env.isTestMode()) {
    stepResult.setFailed('x_fed_day2_ops.test_mode must be true on a declared non-prod instance');
    return;
  }
  stepResult.setSuccess();
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var sam = new x_fed_day2_ops.SamCorrelationClient();
  var lineage = sam.recordLineage(null, 'ATF-SAM-0005', 'atf-correlation-0005', {
    verified_by: 'pull-verify', verified_at: new GlideDateTime().getValue(),
    verified_authority: 'app-owner', verified_status: 'approved', verified_item: 'ATF-Test-Role'
  });
  if (!lineage.ok) { stepResult.setFailed('first-push lineage write failed: ' + JSON.stringify(lineage)); return; }

  var req = new GlideRecord('sc_request');
  req.initialize();
  req.setValue('short_description', 'ATF SAM idempotency fixture — safe to ignore');
  var ritmSysId = req.insert();
  if (!ritmSysId) { stepResult.setFailed('fixture RITM insert failed'); return; }
  var ritmNumber = req.getValue('number');
  outputs.first_ritm_number = ritmNumber;

  var bound = sam.attachRitmToLineage(lineage.sys_id, ritmNumber, '' + ritmSysId);
  bound.ok ? stepResult.setSuccess()
           : stepResult.setFailed('first-push RITM binding failed: ' + JSON.stringify(bound));
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var existing = new GlideRecord(gs.getProperty('x_fed_day2_ops.tbl_integration', 'x_fed_day2_ops_integration'));
  if (!existing.get('sam_request_id', 'ATF-SAM-0005')) {
    stepResult.setFailed('the retried push should find the lineage row written on the first push');
    return;
  }
  var ritmOnRetry = existing.getValue('ritm');
  // The retry must resolve to the ORIGINAL RITM — never mint a second one.
  outputs.retry_ritm_number = ritmOnRetry;
  stepResult.setSuccess();
})(outputs, steps, stepResult);

table = x_fed_day2_ops_integration
conditions = record_type=sam_lineage^sam_request_id=ATF-SAM-0005
assert = exactly one matching row, and its ritm equals both {first_ritm_number from step 200} and {retry_ritm_number from step 300}
